class Node {
  int data;
  Node left;
  Node right;
  Node(int d) {
    data = d;
    left = null;
    right = null;
  }
  static int count(Node n) {
    if (n == null) return 0;
    return 1 + count(n.left) + count(n.right);
  }
  public static void main(String[] args) {
    Node root = new Node(17);
    root.left = new Node(30);
    root.right = new Node(5);
    System.out.println(count(root));
  }
}
